import * as E from './engine.mjs';
import * as G from './goals.mjs';
import * as D from './director.mjs';
import {STORIES,L} from './data.mjs';
import {marketTotal,virtualTotal} from './incidents.mjs';
import {icon,town,miniArt,incidentScene} from './art.mjs';

export function createGameUI(ctx){
  const {tr,tx,esc,cash,date,button,badge,progress,notice,field,select,header,openModal,closeModal,save,toast,render,navigate,formValues,evidenceStore}=ctx;
  const S=()=>ctx.getState(),P=()=>E.activeProfile(S()),J=()=>D.activeJourney(S()),Q=()=>G.currentGoal(S());
  const error='<div class="form-error error" role="alert"></div>';
  let library=false,setupStep=0,draft=null,pendingChoice=null,selectedStory=null;
  const b=(label,action,cls='',attrs='')=>button(label,action,cls,attrs);
  const category=i=>({everyday:tr('Everyday life','日常生活'),minor:tr('A little surprise','小小意外'),milestone:tr('Life milestone','人生里程碑'),rare:tr('A rare turn','罕见转折')})[i.category];
  const stage=s=>({expecting:tr('Expecting in the story','故事中正在孕期'),'new-parent':tr('A new virtual household','新的虚拟家庭'),'toddler-household':tr('A growing virtual family','成长中的虚拟家庭'),homeowner:tr('Virtual homeowner','虚拟房主'),'vehicle-owner':tr('Virtual car owner','虚拟车主'),'independent-household':tr('Living independently','独立生活'),travelling:tr('A virtual traveller','虚拟旅客')})[s?.v2.lifeStage]||tr('Making a virtual life','体验虚拟人生');
  const sceneOf=(s,i)=>incidentScene({incident:i,journey:s,language:S().language});
  function goalCard(){const g=Q(),p=g?G.goalProgress(S(),g):null;return `<section class="card saving-card"><div class="eyebrow">${tr('YOUR REAL SAVINGS GOAL','你的真实储蓄目标')}</div><span class="coin">${icon('coin')}</span><h3>${cash(p?.saved||0,g?.currency)}</h3><p>${g?tr(`of ${cash(g.amount,g.currency)} · your finish line`,`目标${cash(g.amount,g.currency)} · 由你设定`):tr('A goal you choose. A life you discover.','目标由你选择，人生等你探索。')}</p>${progress(p?.saved||0,g?.amount||1)}<div class="mt12">${g&&p.complete?badge(icon('check')+tr('Goal achieved','目标达成')):g?`<span class="tiny">${tr('By','期限')} ${date(g.deadline)} · ${g.paused?tr('Paused','已暂停'):tr('Your own pace','你的节奏')}</span>`:''}</div><button class="textbtn" data-action="${g?'v2-goal':'v2-setup'}">${g?tr('My goal & limits','我的目标与限额'):tr('Set my savings goal','设定我的储蓄目标')}</button></section>`;}
  function goalComplete(){const g=Q(),p=g&&G.goalProgress(S(),g);if(!p?.complete)return '';const lived=G.allChallenges(S(),g.id).filter(x=>x.incident.decision),totals={};for(const x of lived)totals[x.incident.currency]=E.round((totals[x.incident.currency]||0)+x.incident.simulatedExpense);return `<section class="goal-celebration mt"><div class="celebration-spark">${icon('spark')}</div><div><div class="eyebrow">${tr('THIS MILESTONE IS REAL','这个里程碑是真实的')}</div><h2 class="mt8">${tr('You saved your story.','你为故事存下了真实储蓄。')}</h2><p class="small mt8">${tr(`${cash(p.recorded,g.currency)} recorded with reviewed evidence. Your goal stays at ${cash(g.amount,g.currency)}. The virtual story can continue with no more mandatory contributions.`,`已记录${cash(p.recorded,g.currency)}并完成本地凭证审阅。你的目标保持${cash(g.amount,g.currency)}。虚拟故事可继续，无需额外强制储蓄。`)}</p><div class="completion-stats mt12"><span>${tr('Virtual living expenses','虚拟生活开支')}: ${Object.entries(totals).map(([c,v])=>cash(v,c)).join(' · ')||cash(0,g.currency)}</span><span>${lived.length} ${tr('incidents and decisions in this goal','个事件及决定属于此目标')}</span></div><details><summary>${tr('The incidents behind this milestone','里程碑背后的事件')}</summary>${lived.map(x=>`<p class="small">${tx(x.incident.title)} · ${tx(x.incident.decision.title)}</p>`).join('')}</details><div class="flex wrap mt12">${b(tr('Keep living the story','继续体验故事'),'v2-journal','light smallbtn')}${b(tr('Choose a new goal voluntarily','自愿设定新目标'),'v2-newgoal','secondary smallbtn')}</div></div></section>`;}
  function home(){const g=Q(),s=J(),i=s?.v2.current,records=s?.v2.history||[],due=i?.challenge?.schedule.find(p=>p.amount>0)?.due||G.savingsDay(),cp=i?.challenge?G.challengeCredit(S(),i.challenge):null;return header(tr('VIRTUAL LIFE. REAL SAVINGS.','虚拟人生，真实储蓄。'),tr(`Hello, ${esc(S().name)}. What will life bring?`,`你好，${esc(S().name)}。生活会带来什么？`),tr('Virtual expenses become real savings. Your next incident is a surprise.','虚拟开支，变成真实储蓄。下一个事件，等你揭晓。'),badge(tr('Save Your Story · V2','Save Your Story · V2'),'blue'))+
(!g&&S().sessions.length?notice(tr('Your V1 stories, contributions and receipts are preserved. Set a personal V2 goal to continue; earlier savings will not be credited a second time.','V1故事、供款与凭证均已保留。设定个人V2目标后即可继续，早先储蓄不会重复计入。'),'blue')+'<br>':'')+
`<div class="home-layout"><section class="world game-world"><div class="paper-foot"></div><div class="world-heading"><div><h2>${i?tx(i.title):tr('A small town. An unexpected life.','一座小镇，一段意想不到的人生。')}</h2><p>${tr('You bring a savings goal. Life brings the plot.','你带来储蓄目标，生活带来故事情节。')}</p></div>${badge(icon('leaf')+tr('Your virtual world','你的虚拟世界'),'neutral')}</div><div class="world-art">${town()}</div><div class="world-footer"><div class="chapter-icon">${icon(i?'story':'lock')}</div><div class="grow"><h3>${s?tx(STORIES.find(st=>st.id===s.story).title):tr('A life you get to discover','等待你发现的人生')}</h3><p>${i?tr('An incident is waiting in your journal.','日记里有个事件正在等你。'):tr('The next page stays sealed until you open it.','下一页在你打开前保持封存。')}</p></div>${b(!g?tr('Set my savings goal','设定我的储蓄目标'):s&&!s.completed?i?tr('Step into the story','走进故事'):tr('Open the next incident','揭晓下个事件'):tr('Enter virtual life','进入虚拟人生'),!g?'v2-setup':s&&!s.completed?i?'v2-journal':`v2-trigger:${s.v2.turn}`:'v2-library')}</div></section><div class="side-cards">${goalCard()}<section class="card"><div class="flex gap8"><div class="round-icon">${icon('calendar')}</div><h3>${tr('Savings Day','储蓄日')}</h3></div><div class="mini-calendar"><strong>8</strong><div class="small">${tr('Every month, a little progress','每个月，前进一点点')}<br><span class="muted">${date(due)}</span></div></div><p class="small muted">${cp?tr(`${cash(cp.remaining,g.currency)} left for this incident.`,`本事件还需${cash(cp.remaining,g.currency)}。`):tr('Virtual bills, gathered into a real savings statement.','把虚拟账单，汇成真实储蓄清单。')}</p><div class="mt12">${b(tr('Open Savings Day','打开储蓄日'),'nav:savings','secondary smallbtn')}</div></section></div></div>${goalComplete()}${g&&!G.goalProgress(S(),g).complete&&G.goalFeasibility(S(),g).shortfall>0?`<div class="mt">${notice(tr('Your chosen goal needs more time at your current limit. We keep your approved limit and finish line unchanged until you explicitly adjust them.','按当前限额，你的目标需要更多时间。在你明确调整前，限额与目标保持不变。'),'warn')}</div>`:''}
<div class="home-bottom"><section class="card flex"><div class="round-icon">${icon('story')}</div><div><div class="small bold">${tr('Play a life. Don’t buy the milestone.','体验人生，无需真实购买。')}</div><p class="small muted">${tr('You can own a virtual car, welcome a virtual family or renovate a virtual home.','你可以拥有虚拟汽车、迎接虚拟家庭，或装修虚拟房屋。')}</p></div></section><section class="card flex"><div class="round-icon" style="background:#e6eddc">${icon('shield')}</div><div><div class="small bold">${tr('The money stays yours.','钱，始终由你保管。')}</div><p class="small muted">${tr('Deposit in your own bank account. Upload evidence. Review and unlock.','存入自己的银行账户，上传凭证，审阅后解锁。')}</p></div></section></div>
<div class="section-head"><h2>${records.length?tr('Pages you’ve lived','你已体验的篇章'):tr('Ten ways to live another life','十种体验另一种人生的方式')}</h2><button class="textbtn" data-action="v2-library">${tr('Visit the story library','前往故事书库')}</button></div><div class="story-strip">${records.length?records.slice(-3).reverse().map(i=>`<button class="story-mini" data-action="v2-journal"><div class="mini-art ${STORIES.find(st=>st.id===s.story).color}">${sceneOf(s,i)}</div><div class="mini-body"><h3>${tx(i.title)}</h3><p>${tx(i.decision.title)}</p><p>${tr('Virtual expense','虚拟开支')} ${cash(i.simulatedExpense,i.currency)}</p></div></button>`).join(''):STORIES.slice(0,3).map(card).join('')}</div>`;}
  function card(st){return `<button class="story-mini" data-action="v2-preview:${st.id}"><div class="mini-art ${st.color}">${miniArt(st.icon)}</div><div class="mini-body"><div class="flex between mb" style="margin-bottom:12px">${badge(tr('Virtual life','虚拟人生'),'neutral')}</div><h3>${tx(st.title)}</h3><p>${tx(st.subtitle)}</p><p class="small muted mt12">${tx(st.duration)} · ${tr('story-world time','故事世界时间')}</p></div></button>`;}
  function libraryPage(){return header(tr('THE STORY LIBRARY','故事书库'),tr('Which life will you step into?','你想走进哪一种人生？'),tr('All ten virtual lives share your personal savings goal. Future incidents stay hidden.','十种虚拟人生共用你的个人储蓄目标，未来事件保持隐藏。'),b(tr('Back to my story','回到我的故事'),'v2-journal','secondary'))+`<div class="notice blue mb">${tr('A car, a wedding or a child can exist only in the game. Your real goal can be anything you choose. Story time and your savings deadline are separate.','汽车、婚礼或孩子可以只存在于游戏。真实目标由你决定。故事时间与储蓄期限分开。')}</div><div class="library">${STORIES.map(card).join('')}</div>`;}
  function noGoal(){return `<section class="card empty"><div class="illustrated-empty">${miniArt('plant')}</div><h2>${tr('Begin with a goal that is yours.','从属于自己的目标开始。')}</h2><p class="small mt12">${tr('The story will bring the virtual expenses. You choose the real savings finish line and comfortable limit.','故事带来虚拟开支，你决定真实储蓄终点和舒适限额。')}</p><div class="mt">${b(tr('Set my savings goal','设定我的储蓄目标'),'v2-setup')}</div></section>`;}
  function timeline(s){return `<section class="card"><div class="eyebrow muted">${tr('YOUR LIVED PAGES','已体验的篇章')}</div><div class="mini-history mt12">${s.v2.history.slice(-5).map(i=>`<div class="mini-history-row">${icon('check')}<div>${tx(i.title)}<small>${tx(i.decision.title)}</small></div></div>`).join('')}<div class="mini-history-row sealed">${icon('lock')}<div>${tr('The next page is sealed.','下一页仍封存。')}<small>${tr('No future incident is revealed here.','这里不会揭示未来事件。')}</small></div></div></div></section>`;}
  function assets(s){const a=s.v2.assets;return `<section class="card"><h3>${tr('Your virtual household','你的虚拟生活')}</h3><p class="small muted mt12">${stage(s)}</p>${Object.keys(a).length?Object.entries(a).map(([key,v])=>`<div class="cost-row"><span>${({car:tr('Virtual car','虚拟汽车'),property:tr('Virtual property','虚拟房产'),family:tr('Virtual family','虚拟家庭')})[key]||esc(key)}</span><strong>${key==='family'?`${v.babies} ${tr('little ones','个宝宝')}`:cash(v.value,s.marketCurrency)}</strong></div>`).join(''):`<p class="small muted mt12">${tr('Your world changes as you live it.','你的世界会随着体验而改变。')}</p>`}<p class="tiny muted mt12">${tr('These are fictional assets. They do not change your actual financial profile.','这些是虚构资产，不会改变你的真实财务档案。')}</p></section>`;}
  function itemList(items,currency){return `<div class="cost-list">${items.map(i=>`<div class="cost-row"><div>${tx(i.label)}<small>${cash(i.quote??i.typical,i.currency)} × ${i.quantity}${i.simulationShare!==1?` · ${tr('virtual share','虚拟比例')} ${Math.round(i.simulationShare*100)}%`:''}<br>${i.quote!==null?tr('Your unit quotation','你的单位报价'):tr('Illustrative country estimate','各国模拟估计')}</small></div><strong>${cash((i.quote??i.typical)*i.quantity*i.simulationShare,currency)}</strong></div>`).join('')||`<p class="small muted mt12">${tr('No additional virtual payment in this response.','此应对没有额外虚拟付款。')}</p>`}</div>`;}
  function challengeBlock(i){const g=Q(),c=i.challenge,credit=G.challengeCredit(S(),c),oldGoal=G.ensureGame(S()).goals.find(g=>g.id===c.goalId),oldComplete=G.goalProgress(S(),oldGoal).complete;return `<section class="card mt"><div class="flex between wrap"><div><div class="eyebrow muted">${tr('YOUR CHOICE IS PART OF THE STORY','你的选择，已成为故事的一部分')}</div><h3 class="mt8">${tx(i.decision.title)}</h3></div>${badge(icon('check')+tr('Saved','已保存'))}</div><p class="small muted mt12">${tx(i.immediate)}</p>${i.discovery?`<div class="notice mt12">${tx(i.discovery)}</div>`:''}<p class="small mt12"><strong>${tr('Later in this life:','这段人生稍后：')}</strong> ${tx(i.delayed)}</p><div class="incident-values mt"><div><span>${tr('Estimated market cost','估计市场成本')}</span><strong>${cash(i.estimatedMarketCost,i.currency)}</strong></div><div><span>${tr('Virtual incident expense','虚拟事件开支')}</span><strong>${cash(i.simulatedExpense,i.currency)}</strong></div><div><span>${tr('Assigned real savings','指定真实储蓄')}</span><strong>${cash(c.assigned,c.currency)}</strong></div></div><p class="small muted mt12">${tr('These three values are separate. The game does not spend the virtual expense or collect your savings.','这三个金额分开记录。游戏不会支付虚拟开支，也不会收取你的储蓄。')}</p>${c.unassignedExpense>0&&!oldComplete?`<div class="notice blue mt12">${tr(`${cash(c.unassignedExpense,c.currency)} of the virtual expense is not converted into this checkpoint. This is an affordable portion, not payment of the full virtual bill.`,`${cash(c.unassignedExpense,c.currency)}的虚拟开支未转化为本次目标。这是可负担部分，并非全额虚拟账单。`)}</div>`:''}${oldComplete?`<div class="notice mt12">${tr('This goal is achieved. Continue the storyline without another mandatory contribution.','此目标已完成，可以继续故事，无需额外强制储蓄。')}</div>`:''}<div class="mt">${progress(credit.paid,c.assigned||1)}</div><div class="flex between mt12 small"><span>${tr('Reviewed contribution','已审阅供款')} ${cash(credit.paid,c.currency)}</span><strong>${cash(credit.remaining,c.currency)} ${tr('remaining','剩余')}</strong></div>${c.schedule.length?`<div class="checkpoint-dates mt12">${c.schedule.map(p=>`<span>${icon('calendar')}${date(p.due)} · ${cash(p.amount,c.currency)}</span>`).join('')}</div>`:!oldComplete?`<p class="small muted mt12">${tr('No mandatory contribution could be scheduled within the approved limits. You may lower the goal or extend its duration explicitly.','在已批准限额内无法安排强制供款。你可以明确降低目标或延长时长。')}</p>`:''}<div class="form-actions">${credit.remaining>0?b(tr('Upload savings evidence','上传储蓄凭证'),'v2-deposit','secondary'):''}${!oldComplete&&c.assigned>0?b(tr('Adjust checkpoint','调整储蓄点'),'v2-checkpoint','light'):''}${b(tr('Turn this page','翻过这一页'),`v2-finish:${i.id}`,'',D.canUnlock(S())?'':'disabled')}</div><p class="tiny muted mt12">${tr('Early contributions are welcome. The 8th is your monthly Savings Day, not a fake bank-settlement date. Pending receipts do not unlock incidents.','可以提前供款。每月8日是储蓄日，并非虚构银行到账日期。待审凭证不会解锁事件。')}</p></section>`;}
  function journal(){const s=J(),g=Q();if(library)return libraryPage();if(!g)return header('',tr('Your story begins with your own goal.','你的故事，始于自己的目标。'),'')+noGoal();if(!s)return libraryPage();if(s.completed)return header(tr('A VIRTUAL LIFE, LIVED','已体验的一段虚拟人生'),tx(STORIES.find(st=>st.id===s.story).title),tr('Your goal belongs to you, beyond any single storyline.','你的目标属于你，不受单一故事限制。'))+goalComplete()+`<section class="card text-center mt"><div class="story-preview-art">${miniArt(STORIES.find(st=>st.id===s.story).icon)}</div><h2>${tr('A life full of little decisions.','一段由小决定组成的人生。')}</h2><p class="small muted mt12">${s.v2.history.length} ${tr('incidents experienced','个事件已体验')} · ${cash(D.lifeSummary(s).virtualExpenses,s.marketCurrency)} ${tr('virtual expenses','虚拟开支')}</p>${s.story==='car'?`<p class="small muted mt12">${tr('Your two-year virtual story ends here. A longer simulated vehicle loan is still outstanding.','两年的虚拟故事在此结束，更长期的模拟车辆贷款仍未偿清。')}</p>`:''}<div class="mt">${b(tr('Try another virtual life','体验另一种虚拟人生'),'v2-library')}</div></section>`+pastPages(s);
    const i=s.v2.current;const intro=header(tx(STORIES.find(st=>st.id===s.story).title),i?tx(i.title):tr('A sealed envelope is waiting.','一封封存的信正在等你。'),tr(`Virtual month ${s.v2.month} · ${s.v2.history.length} pages lived`,`虚拟第${s.v2.month}月 · 已体验${s.v2.history.length}页`),badge(tr('Story life · fictional','故事生活 · 虚构'),'blue'));
    const paused=g.paused?`<div class="notice warn mb">${tr('Your adventure is paused. Your goal and story outcomes are preserved.','冒险已暂停，目标和故事结果均已保留。')} <button class="textbtn" data-action="v2-pause">${tr('Resume gently','轻松继续')}</button></div>`:'';
    if(!i)return intro+paused+`<div class="journal-layout"><section class="card sealed-page"><div class="sealed-art">${envelope()}</div><div class="eyebrow muted">${tr('LIFE HAS A NEW PAGE FOR YOU','生活为你准备了新的一页')}</div><h2 class="mt12">${tr('You’ll find out when you open it.','打开时，你就会知道。')}</h2><p class="small muted mt12">${tr('Your past choices, virtual household and comfortable savings limit shape which incident can arrive next.','过去的选择、虚拟生活与舒适储蓄限额，共同影响下一个可能到来的事件。')}</p><div class="mt">${b(tr('Open the next incident','揭晓下个事件'),`v2-trigger:${s.v2.turn}`,'',g.paused?'disabled':'')}</div></section><aside class="stack" style="align-content:start">${assets(s)}${timeline(s)}</aside></div>`+goalComplete();
    return intro+paused+`<div class="journal-layout"><div><section class="scene"><div class="scene-art v2-scene">${sceneOf(s,i)}</div><div class="scene-caption"><div class="flex between wrap">${badge(category(i),i.category==='rare'?'rose':'neutral')}<span class="tiny muted">${tr('Virtual month','虚拟月份')} ${i.month}</span></div><h2 class="mt12">${tx(i.title)}</h2></div></section><p class="dialogue">${tx(i.intro)}</p><blockquote class="character-dialogue">${tx(i.dialogue)}</blockquote>${s.story==='baby'?`<div class="notice blue small">${tr('A fictional family journey, not a clinical timetable. Twins are a one-time 1% game outcome unless preconfigured; only relevant cost quantities change.','这是虚构家庭旅程，并非临床时间表。除预设情况外，双胎是一次性1%游戏结果，只调整相关成本数量。')}</div>`:''}${i.decision?challengeBlock(i):`<div class="section-head"><h3>${tr('How will you respond?','你会如何应对？')}</h3><button class="textbtn" data-action="v2-quotes">${tr('Edit unit quotes','编辑单位报价')}</button></div><div class="decisions">${i.options.map(o=>`<button class="decision" data-action="v2-choice:${i.id}:${o.id}" ${g.paused?'disabled':''}><span class="choice-circle"></span><span class="grow"><strong>${tx(o.title)}</strong><small>${tx(o.description)}</small><span class="choice-cost">${tr('Virtual expense','虚拟开支')} ${cash(virtualTotal(o.items),i.currency)}</span></span></button>`).join('')}</div>`}<section class="card mt"><h3>${tr('An honest record of this incident','清楚记录本次事件')}</h3>${itemList(i.items||i.options[0].items,i.currency)}<p class="tiny muted mt12">${tr('Independent Malaysian and Singaporean estimates. Unit quotations are frozen for decided incidents; the director changes scope and schedules, never the same product’s market price to match a goal.','马来西亚与新加坡采用独立估计。已决定事件的单位报价会保存快照。导演调整范围与时间安排，不会为了配合目标而改变相同产品的市场价格。')}</p><details><summary>${tr('Why this incident could arrive','为何本次事件符合条件')}</summary><p>${tr('Selected using your remaining goal, remaining Savings Days, approved monthly capacity, current story, prior decisions, life stage, virtual assets and already experienced incidents. Future eligible incidents stay hidden.','选择依据包括剩余目标、剩余储蓄日、已批准每月能力、当前故事、过去决定、人生阶段、虚拟资产与已体验事件。未来合资格事件保持隐藏。')}</p></details></section>${pastPages(s)}</div><aside class="stack" style="align-content:start">${goalCard()}${assets(s)}${timeline(s)}</aside></div>`+goalComplete();
  }
  function envelope(){return `<svg viewBox="0 0 320 190" role="img" aria-label="${tr('A sealed story envelope','封存的故事信封')}"><g class="float"><path d="M55 52h210v112H55z" fill="#f5e8c6" stroke="#ad9c73" stroke-width="2"/><path d="m55 52 105 77L265 52M55 164l73-67m137 67-73-67" fill="none" stroke="#b4a37c" stroke-width="2"/><circle cx="160" cy="112" r="17" fill="#879d79"/><path d="M153 114q3-13 14-13-2 14-14 13m0 0-2 7" fill="none" stroke="#f8f6e9" stroke-width="2"/></g><g stroke="#c3ab6d" stroke-width="2"><path d="M34 35v12m-6-6h12m245 83v12m-6-6h12"/></g></svg>`;}
  function pastPages(s){return `<details class="mt"><summary>${tr('Your incident journal','你的事件日记')} · ${s.v2.history.length}</summary>${s.v2.history.map(i=>`<div class="cost-row"><div><strong>${tx(i.title)}</strong><small>${tx(i.decision.title)}<br>${tr('Virtual','虚拟')} ${cash(i.simulatedExpense,i.currency)} · ${tr('Savings challenge','储蓄挑战')} ${cash(i.challenge.assigned,i.challenge.currency)}</small></div><span class="tiny muted">${date(i.completed)}</span></div>`).join('')}${s.v2.legacyHistoryCount?`<p class="small muted mt12">${tr(`${s.v2.legacyHistoryCount} V1 chapters are also retained in your original story archive.`,`${s.v2.legacyHistoryCount}个V1章节也保留在原故事档案中。`)}</p>`:''}</details>`;}
  function savings(){const g=Q(),s=J();if(!g)return header('',tr('Turn virtual expenses into real progress.','把虚拟开支变成真实进步。'),'')+noGoal();const p=G.goalProgress(S(),g),statements=G.savingsStatement(S(),g),profile=P(),reserves=E.reserves(S(),profile),pending=S().ledger.filter(t=>t.goalId===g.id&&t.status==='pending');return header(tr('SAVINGS DAY · THE 8TH','储蓄日 · 每月8日'),tr('Virtual bills. Real savings.','虚拟账单，真实储蓄。'),tr('Deposit in your own account, upload evidence, review the details, and unlock the next incident.','存入自己的账户，上传凭证，审阅明细，解锁下一个事件。'),b(icon('upload')+tr('Record a deposit','记录存款'),'v2-deposit'))+`<div class="grid2">${goalCard()}<section class="card"><div class="flex between"><h3>${tr('A separate safety net','独立的安全网')}</h3><button class="textbtn" data-action="emergency">${tr('Adjust','调整')}</button></div><div class="metric">${cash(reserves,profile.currency)}</div><p class="small muted mt12">${tr(`${cash(profile.emergency,profile.currency)} planned monthly, separate from the main goal.`,`每月计划${cash(profile.emergency,profile.currency)}，独立于主目标。`)}</p><p class="small muted mt8">${tr('One deposit can be split, but its accepted amount can never be credited twice. An optional missed emergency contribution does not block your story.','一笔存款可分配，但获接受金额不会重复计入。错过可选应急供款不会阻止故事。')}</p></section></div>${goalComplete()}<div class="notice blue mt">${tr('Local evidence review checks file format, duplicate references, duplicate file hashes and allocation totals, followed by your explicit review. It does not confirm bank settlement. This build has no bank connection or independent verifier.','本地凭证审阅会检查文件格式、重复参考号、重复文件哈希和分配总额，再由你明确审阅。它不能确认银行到账。此版本没有银行连接或独立审核员。')}</div>${pending.length?`<div class="notice warn mt">${pending.length} ${tr('receipt(s) awaiting review. These do not count towards progress.','份凭证待审阅，尚未计入进度。')}</div>`:''}<div class="section-head"><h2>${tr('Your monthly incident statement','每月事件储蓄清单')}</h2><span class="small muted">${tr('Every 8th','每月8日')}</span></div>${statements.length?statements.map(st=>`<section class="card statement-card"><div class="flex between wrap"><h3>${date(st.due)}</h3>${badge(tr('Savings Day','储蓄日'),'yellow')}</div>${st.incidents.map(i=>`<div class="statement-incident"><div><strong>${tx(i.title)}</strong><p class="tiny muted mt8">${tr('Market estimate','市场估计')} ${cash(i.marketCost,i.marketCurrency)} · ${tr('Virtual expense','虚拟开支')} ${cash(i.simulatedExpense,i.marketCurrency)}</p></div><div class="right"><strong>${cash(i.assigned,g.currency)}</strong><small>${cash(i.paid,g.currency)} ${tr('reviewed','已审阅')}</small></div></div>`).join('')}<hr class="rule"><div class="flex between small"><span>${tr('Statement challenge','本期储蓄挑战')}</span><strong>${cash(st.assigned,g.currency)}</strong></div><div class="mt12">${progress(st.paid,st.assigned)}</div><p class="tiny muted mt12">${cash(st.limit,g.currency)} ${tr('approved main-goal limit for this period. Early saving is allowed.','为本期已批准主目标限额，可以提前储蓄。')}</p></section>`).join(''):`<section class="empty">${icon('calendar')}<h3>${tr('Your next incident will write the first line.','下个事件会写下第一行。')}</h3><p class="small">${tr('The 8th is reserved for Savings Day. Open an incident and make a choice to receive a challenge.','每月8日为储蓄日。打开事件并做出选择，即可生成挑战。')}</p><div class="mt12">${b(tr('Return to virtual life','回到虚拟人生'),'v2-journal','secondary')}</div></section>`}<div class="section-head"><h2>${tr('Your evidence journal','你的凭证日记')}</h2></div><div class="receipt-list">${S().ledger.length?S().ledger.slice().reverse().map(t=>`<section class="receipt"><div class="flex between wrap"><div><h4>${esc(t.reference)}</h4><p class="small muted mt8">${date(t.date)} · ${esc(t.fileName||tr('V1 manual record','V1手动记录'))}</p></div><div class="right"><strong>${cash(t.amount,t.currency)}</strong><div class="mt8">${badge(t.status==='confirmed'?tr('Reviewed locally','已完成本地审阅'):t.status==='pending'?tr('Awaiting review','待审阅'):tr('Rejected','已拒绝'),t.status==='pending'?'yellow':t.status==='rejected'?'rose':'')}</div></div></div><p class="small muted mt12">${tr('Goal allocation','目标分配')} ${cash(t.main,t.currency)} · ${tr('Emergency','应急')} ${cash(t.emergency,t.currency)} · ${tr('Unallocated','未分配')} ${cash(t.amount-t.main-t.emergency,t.currency)}</p>${!t.goalId?`<p class="tiny muted mt8">${tr('Preserved V1 contribution; not credited again to a V2 goal.','保留的V1供款，不会重复计入V2目标。')}</p>`:''}<div class="flex wrap mt12">${t.status==='pending'?b(tr('Review evidence','审阅凭证'),`review:${t.id}`,'secondary smallbtn'):''}${t.fileName?`<button class="textbtn" data-action="v2-evidence:${t.id}">${tr('View local receipt','查看本地凭证')}</button>`:''}</div></section>`).join(''):`<section class="empty">${icon('leaf')}<h3>${tr('A first small step is enough.','先迈出小小一步就够了。')}</h3><p class="small">${tr('Your receipt-reviewed contributions will appear here.','完成凭证审阅的供款会显示在这里。')}</p></section>`}</div>`;}
  function goalPanel(){const g=Q();if(!g)return noGoal();const p=G.goalProgress(S(),g),feas=G.goalFeasibility(S(),g),all=G.ensureGame(S()).goals;return `<section class="card mb"><div class="flex between wrap"><div><div class="eyebrow muted">${tr('YOUR GAME, YOUR LIMITS','你的游戏，你的限额')}</div><h2 class="mt8">${esc(g.name)}</h2></div>${badge(p.complete?tr('Achieved','已达成'):g.paused?tr('Paused','已暂停'):tr('In progress','进行中'))}</div><div class="incident-values mt"><div><span>${tr('Personal savings goal','个人储蓄目标')}</span><strong>${cash(g.amount,g.currency)}</strong></div><div><span>${tr('Main-goal monthly limit','主目标每月限额')}</span><strong>${cash(feas.limit,g.currency)}</strong></div><div><span>${tr('Goal deadline','目标期限')}</span><strong>${date(g.deadline)}</strong></div></div><p class="small muted mt12">${tr('Your comfortable total limit includes the optional emergency allocation. Virtual life events cannot change these limits or your actual income.','舒适总限额包含可选应急分配。虚拟事件不能改变这些限额或你的真实收入。')}</p><div class="flex wrap mt">${b(p.complete?tr('Start a new goal voluntarily','自愿开始新目标'):tr('Adjust goal & duration','调整目标与时长'),p.complete?'v2-newgoal':'v2-adjustgoal','secondary smallbtn')}${!p.complete?b(g.paused?tr('Resume adventure','继续冒险'):tr('Pause adventure','暂停冒险'),'v2-pause','light smallbtn'):''}${b(tr('Review personal limits','审阅个人限额'),'editprofile','light smallbtn')}</div><details><summary>${tr('Goal adjustment audit','目标调整审计')} · ${g.audit.length}</summary>${g.audit.map(a=>`<div class="cost-row"><div>${esc(a.type)}<small>${esc(a.reason||tr('Savings milestone recorded','已记录储蓄里程碑'))}${a.before?`<br>${cash(a.before.amount,g.currency)} → ${cash(a.after.amount,g.currency)} · ${a.before.months} → ${a.after.months} ${tr('months','个月')}`:''}</small></div><span class="tiny muted">${date(a.date)}</span></div>`).join('')}</details>${all.length>1?`<p class="small muted mt12">${all.filter(g=>g.completedAt).length} ${tr('personal goal(s) achieved. Earlier deposits are never reused for a new goal.','个个人目标已达成。早先存款不会重复用于新目标。')}</p>`:''}</section>`;}
  function setupModal(fresh=false){const p=P(),g=Q();setupStep=0;draft={name:S().name,country:p?.country||'MY',currency:g?.currency||p?.currency||'MYR',incomeCurrency:p?.incomeCurrency||p?.currency||'MYR',language:S().language,goalName:fresh?tr('My next savings adventure','我的下一段储蓄冒险'):tr('My savings adventure','我的储蓄冒险'),amount:2400,months:6,comfortableMonthly:600,income:p?.income??0,fixed:p?.fixed??0,living:p?.living??0,discretionary:p?.discretionary??0,loans:p?.loans??0,emergency:p?.emergency??0,fx:p?.fx||3.3,fxDate:p?.fxDate||E.today(),savings:p?E.recordedSavings(S(),p):0,reserves:p?E.reserves(S(),p):0};showSetup();}
  function showSetup(){const d=draft,steps=`<div class="steps">${[0,1,2].map(i=>`<span class="${i<=setupStep?'done':''}"></span>`).join('')}</div>`;const first=`<div class="story-preview-art">${miniArt('plant')}</div><h3>${tr('Your goal is real. Your next life is virtual.','目标是真实的，下一种人生是虚拟的。')}</h3><p class="small muted mt12">${tr('You don’t need to want a real car, wedding or child. Set your own goal and let virtual life provide surprising reasons to save.','你不需要真实购车、结婚或育儿意愿。设定自己的目标，让虚拟生活带来意外的储蓄理由。')}</p><div class="form-grid mt">${field(tr('Your name','你的称呼'),'name',d.name,'text','','required maxlength="40"')}${select(tr('Language','语言'),'language',d.language,[['en','English'],['zh','简体中文']])}${select(tr('Country / market','国家／市场'),'country',d.country,[['MY',tr('Malaysia','马来西亚')],['SG',tr('Singapore','新加坡')]])}${select(tr('Savings goal currency','储蓄目标币种'),'currency',d.currency,[['MYR','MYR · RM'],['SGD','SGD · S$']])}${field(tr('My total savings goal','我的储蓄总目标'),'amount',d.amount,'number','','min="0.01" required')}${field(tr('Challenge duration (months)','挑战时长（月）'),'months',d.months,'number','','min="1" max="120" step="1" required')}<div class="full">${field(tr('Comfortable total monthly savings (including emergency)','舒适的每月储蓄总额（含应急）'),'comfortableMonthly',d.comfortableMonthly,'number',tr('This is an upper limit, not a promise to spend or save that much.','这是上限，并非必须花费或储蓄的承诺。'),'required')}</div></div>`;
    const second=`<h3>${tr('Keep the game comfortable.','让游戏保持轻松。')}</h3><p class="small muted mt12">${tr(`Income is entered in its own currency. Commitments are in ${d.country==='MY'?'MYR':'SGD'}. These numbers set safe limits; no virtual event changes them.`,`收入使用其本身币种，责任开支使用${d.country==='MY'?'MYR':'SGD'}。这些数字只设定安全限额，虚拟事件不会改变它们。`)}</p><button class="textbtn mt12" type="button" data-action="v2-sample">${tr('Use labelled sample amounts for the local demo','在本地演示中使用已标明的示例金额')}</button><div class="form-grid mt">${select(tr('Income currency','收入币种'),'incomeCurrency',d.incomeCurrency,[['MYR','MYR'],['SGD','SGD']])}${field(tr('Actual monthly net income','实际每月净收入'),'income',d.income,'number','','required')}${field(tr('Fixed commitments, excluding loans','固定责任，不含贷款'),'fixed',d.fixed)}${field(tr('Essential living expenses','必要生活开支'),'living',d.living)}${field(tr('Optional spending buffer','可选开支缓冲'),'discretionary',d.discretionary)}${field(tr('Existing monthly loan repayments','已有每月贷款供款'),'loans',d.loans)}${field(tr('Optional monthly emergency contribution','可选每月应急供款'),'emergency',d.emergency)}${field(tr('MYR per 1 SGD (editable assumption)','每1 SGD的MYR（可编辑假设）'),'fx',d.fx,'number','','min="0.0001" step="0.0001" required')}${field(tr('Exchange-rate date','汇率日期'),'fxDate',d.fxDate,'date','','required')}</div>`;
    const native=d.country==='MY'?'MYR':'SGD',mock={...d,currency:native},nativeCap=E.capacity(mock).available,main=Math.max(0,Math.min(G.exchange(nativeCap,native,d.currency,d.fx),d.comfortableMonthly-G.exchange(d.emergency,native,d.currency,d.fx))),pace=d.amount/d.months;const review=`<div class="story-preview-art">${miniArt('book')}</div><h3>${tr('A goal with room to breathe.','留有余地的目标。')}</h3><div class="cost-list mt"><div class="cost-row"><span>${tr('Your personal finish line','你的个人终点')}</span><strong>${cash(d.amount,d.currency)}</strong></div><div class="cost-row"><span>${tr('Main-goal monthly upper limit','主目标每月上限')}</span><strong>${cash(main,d.currency)}</strong></div><div class="cost-row"><span>${tr('Chosen duration','所选时长')}</span><strong>${d.months} ${tr('months','个月')}</strong></div><div class="cost-row"><span>${tr('First Savings Day','首个储蓄日')}</span><strong>${date(G.savingsDay())}</strong></div></div><div class="notice ${pace>main?'warn':''} mt12">${pace>main?tr('This goal needs more time at your current limit. We will not raise your limit or invent income. You can go back to lower the goal or extend the duration.','按当前限额，此目标需要更多时间。我们不会提高限额或虚构收入。你可以返回降低目标或延长时长。'):tr('The director will fit contributions within the approved limit. Full virtual prices and partial real challenges stay clearly separate.','导演会把供款安排在已批准限额内。完整虚拟价格与部分真实挑战保持清楚分开。')}</div><label class="check mt"><input name="approval" type="checkbox" required>${tr('I approve this goal and monthly limit. The app may not increase them automatically. I understand receipt review is local self-attestation, not bank settlement verification.','我批准此目标及每月限额，应用不能自动增加。我理解凭证审阅是本地自行确认，并非银行到账验证。')}</label>`;
    openModal(tr('Set your savings adventure','设定储蓄冒险'),`${steps}<form id="v2-setup-form">${setupStep===0?first:setupStep===1?second:review}${error}<div class="form-actions">${setupStep?b(tr('Back','返回'),'v2-setup-back','secondary','type="button"'):''}<button class="btn" type="submit">${setupStep===2?tr('Approve goal & enter virtual life','批准目标并进入虚拟人生'):tr('Continue','继续')}</button></div></form><p class="tiny muted mt12">${tr('Local demo: no money transfers, bank access or cross-device account is created.','本地演示：不会创建资金转移、银行访问或跨设备账户。')}</p>`);
  }
  function preview(storyId){selectedStory=storyId;const st=STORIES.find(s=>s.id===storyId),s=J(),g=Q();openModal(tx(st.title),`<div class="story-preview-art ${st.color}">${miniArt(st.icon)}</div><p class="muted">${tx(st.subtitle)}</p><div class="flex wrap mt12">${badge(tr('Playable virtual life','可体验虚拟人生'))}${badge(tx(st.duration),'neutral')}</div><div class="notice blue mt">${tr('This is a fictional life, not a plan to make this purchase or commitment in reality. Your personal savings goal and comfort limit stay the same. Future incidents remain sealed.','这是一种虚构人生，并非在现实中购买或承担此责任的计划。个人储蓄目标和舒适限额保持不变，未来事件仍封存。')}</div>${s&&!s.completed?`<div class="notice warn mt">${tr('You already have an active virtual life. Continue it before choosing a different main storyline. Your emergency plan can run alongside it.','你已有进行中的虚拟人生。请先继续此主线，再选择其他故事。应急计划可以并行。')}</div><div class="mt">${b(tr('Return to my life','回到我的人生'),'v2-journal')}</div>`:`<form id="v2-story-form" class="mt">${storyId==='baby'?`<label class="check"><input name="knownTwins" type="checkbox">${tr('Choose the known-twins virtual branch before starting','开始前选择已知双胎虚拟分支')}</label><p class="tiny muted mt8">${tr('Otherwise a single 1% twin game roll happens at confirmation, after the pregnancy-test scene. It is not a medical statistic.','否则，在验孕场景后的确认阶段进行一次1%双胎游戏抽选。这不是医学统计。')}</p>`:''}${storyId==='travel'?`<div class="form-grid">${field(tr('Virtual destination','虚拟目的地'),'destination','Penang','text','','maxlength="80"')}${field(tr('Virtual travellers','虚拟旅客人数'),'travellers',1,'number','','min="1" max="8" step="1"')}</div>`:''}${storyId==='car'?`<p class="small muted">${tr('You will choose the virtual vehicle, inspection and coverage as the story unfolds. Financing and ownership costs remain fictional.','故事展开后，你会选择虚拟车辆、检查及保障。融资与拥车成本均为虚构。')}</p>`:''}<label class="check mt"><input name="ack" type="checkbox" required>${tr('I understand this is virtual life and my real funds stay in my own bank account.','我理解这是虚拟人生，真实资金保留在自己的银行账户。')}</label>${error}<div class="form-actions"><button class="btn" type="submit">${g?tr('Step into this virtual life','走进这段虚拟人生'):tr('Set my goal first','先设定我的目标')}</button></div></form>`}`);}
  function choiceModal(){const s=J(),i=s?.v2.current,o=i?.options.find(o=>o.id===pendingChoice?.optionId);if(!o||i.id!==pendingChoice.incidentId)throw Error('Choose a response to the current incident.');const plan=G.conversionPlan(S(),{...i,estimatedMarketCost:marketTotal(o.items)},virtualTotal(o.items),i.currency,{mode:pendingChoice.mode,proportion:pendingChoice.share/100});openModal(tr('A virtual expense, a real saving','一笔虚拟开支，一份真实储蓄'),`<h3>${tx(o.title)}</h3>${itemList(o.items,i.currency)}<div class="incident-values mt"><div><span>${tr('Market estimate','市场估计')}</span><strong>${cash(marketTotal(o.items),i.currency)}</strong></div><div><span>${tr('Virtual expense','虚拟开支')}</span><strong>${cash(virtualTotal(o.items),i.currency)}</strong></div><div><span>${tr('Real savings assigned','指定真实储蓄')}</span><strong>${cash(plan.assigned,plan.currency)}</strong></div></div><form id="v2-decision-form" class="mt"><div class="form-grid">${select(tr('How to convert this incident','如何转化此事件'),'mode',pendingChoice.mode,[['portion',tr('An affordable slice on one Savings Day','一个储蓄日的舒适部分')],['spread',tr('Spread the share over eligible Savings Days','将比例分配至合资格储蓄日')]])}${field(tr('Maximum share of the virtual expense (%)','虚拟开支的最高转化比例（%）'),'share',pendingChoice.share,'number','','min="0" max="100" step="1" required')}</div><button class="textbtn mt12" type="button" data-action="v2-preview-plan">${tr('Update the savings preview','更新储蓄预览')}</button><div class="notice mt12">${plan.schedule.length?plan.schedule.map(p=>`${date(p.due)} · ${cash(p.amount,plan.currency)}`).join('<br>'):tr('No mandatory contribution is assigned.','没有指定强制供款。')}</div><p class="small muted mt12">${plan.unassignedExpense>0?tr(`${cash(plan.unassignedExpense,plan.currency)} of the virtual expense is not converted into this checkpoint.`,`${cash(plan.unassignedExpense,plan.currency)}的虚拟开支未转化为本次储蓄点。`):tr('The full virtual amount is assigned. It is credited only after receipt review.','完整虚拟金额已指定，仅在凭证审阅后计入。')}</p><p class="small muted mt8">${tr('You save in your own bank account. No real purchase, loan or payment to this app is required.','你在自己的银行账户储蓄，无需真实购买、贷款或付款给此应用。')}</p>${error}<div class="form-actions"><button class="btn" type="submit">${tr('Choose this response & save the plan','选择此应对并保存计划')}</button></div></form>`);}
  function goalModal(){const g=Q();if(!g)return setupModal();openModal(tr('Your personal savings goal','你的个人储蓄目标'),goalPanel()+`<div class="notice blue">${tr('Virtual expenses influence incident selection and contribution schedules. They never move your real savings finish line.','虚拟开支影响事件选择和供款安排，不会移动你的真实储蓄终点。')}</div>`);}
  function adjustGoalModal(){const g=Q();openModal(tr('An adjustment you approve','由你批准的调整'),`<p class="small muted">${tr('You can lower or explicitly raise the goal, extend its original duration, or change the comfortable limit. Every change is recorded; past market costs stay frozen.','你可以降低或明确提高目标、延长原时长，或改变舒适限额。每次更改都会记录，过去市场成本快照保持不变。')}</p><form id="v2-goal-form" class="mt"><div class="form-grid">${field(tr('Revised total goal','调整后的总目标'),'amount',g.amount,'number','','min="0.01" required')}${field(tr('Total duration from original start (months)','从原开始日起的总时长（月）'),'months',g.months,'number','','min="1" max="120" step="1" required')}<div class="full">${field(tr('Comfortable total monthly savings','舒适的每月储蓄总额'),'comfortableMonthly',g.comfortableMonthly,'number','','required')}</div><div class="full">${field(tr('Reason for this adjustment','调整原因'),'reason','','text','','required maxlength="200"')}</div></div><label class="check mt"><input name="approved" type="checkbox" required>${tr('I explicitly approve these revised limits and finish line.','我明确批准调整后的限额与终点。')}</label>${error}<div class="form-actions"><button class="btn" type="submit">${tr('Approve & record adjustment','批准并记录调整')}</button></div></form>`);}
  function pauseModal(){const g=Q();openModal(g.paused?tr('Welcome back, at your pace','欢迎回来，按你的节奏'):tr('Take a little breathing room','留一点喘息空间'),`<p class="small muted">${tr('Pausing preserves outcomes and blocks new incident choices. It does not move your deadline automatically. Extend the goal explicitly if you need more time.','暂停会保留结果，并阻止新事件选择。它不会自动移动期限。如需更多时间，请明确延长目标。')}</p><form id="v2-pause-form" class="mt">${field(tr('A short note for your journal','留给日记的一句话'),'reason',g.paused?tr('Ready to continue','准备继续'):tr('Taking a break','暂时休息'),'text','','required maxlength="200"')}${error}<div class="form-actions"><button class="btn" type="submit">${g.paused?tr('Resume adventure','继续冒险'):tr('Pause adventure','暂停冒险')}</button></div></form>`);}
  function checkpointModal(){const i=J()?.v2.current,c=i?.challenge;if(!c)return;const paid=G.challengeCredit(S(),c).paid;openModal(tr('A gentler checkpoint','更轻松的储蓄点'),`<p class="small muted">${tr('Lower this optional game requirement when needed. The full virtual expense remains unchanged and visible.','需要时降低可选游戏要求，完整虚拟开支仍保持不变并清楚显示。')}</p><form id="v2-checkpoint-form" class="mt"><div class="form-grid">${field(tr('Revised assigned savings','调整后的指定储蓄'),'target',Math.max(paid,Math.min(c.assigned,G.monthLimit(S(),Q()))),'number','',`min="${paid}" max="${c.assigned}" required`)}${field(tr('Adjustment reason','调整原因'),'reason','','text','','required maxlength="200"')}</div>${error}<div class="form-actions"><button class="btn" type="submit">${tr('Record a lower checkpoint','记录较低储蓄点')}</button></div></form>`);}
  function quotesModal(){const i=J()?.v2.current;if(!i||i.decision)return;const items=Array.from(new Map(i.options.flatMap(o=>o.items).map(i=>[i.id,i])).values());openModal(tr('Your unit quotations','你的单位报价'),`<p class="small muted">${tr('Enter a quote for the same item or service, not a price chosen to fit the savings target. Quantity and virtual payment share are applied separately.','输入相同项目或服务的报价，而非为配合储蓄目标选择的价格。数量与虚拟付款比例分开应用。')}</p><form id="v2-quotes-form" class="mt"><div class="form-grid">${items.map(i=>field(tx(i.label)+` · ${i.currency}`,`quote_${i.id}`,i.quote??i.typical)).join('')}<div class="full">${field(tr('Quotation source / note','报价来源／备注'),'reason','','text','','required maxlength="200"')}</div></div>${error}<div class="form-actions"><button class="btn" type="submit">${tr('Save quotation snapshot','保存报价快照')}</button></div></form>`);}
  function depositModal(){const g=Q(),s=J(),p=P();if(!g||!s){toast(tr('Set a goal and enter a virtual life before recording goal savings.','记录目标储蓄前，请先设定目标并进入虚拟人生。'));return;}const remaining=G.goalProgress(S(),g),outstanding=s.v2.current?.challenge?G.challengeCredit(S(),s.v2.current.challenge).remaining:0;openModal(tr('Record money you saved','记录你存下的资金'),`<p class="small muted">${tr('Transfer to your own bank account first. A receipt is required for a new V2 contribution. Partial payments and grouped transfers are supported.','请先转入自己的银行账户。新增V2供款必须上传凭证，支持部分供款及合并转账。')}</p><form id="v2-deposit-form" class="mt"><div class="form-grid">${field(tr('Actual transfer amount','真实转账金额'),'amount','','number','','min="0.01" required')}${select(tr('Transfer currency','转账币种'),'currency',g.currency,Array.from(new Set([g.currency,p.currency])).map(c=>[c,c]))}${field(tr('Actual transfer date','真实转账日期'),'date',E.today(),'date','',`max="${E.today()}" required`)}${field(tr('Unique transfer / batch reference','唯一转账／批次参考号'),'reference','','text','','required minlength="3" maxlength="100"')}${field(tr('Allocate to personal goal','分配至个人目标'),'main',Math.min(outstanding,Math.max(0,remaining.remaining-remaining.pending)),'number',tr(`Remaining uncredited goal: ${cash(remaining.remaining-remaining.pending,g.currency)}`,`剩余未计入目标：${cash(remaining.remaining-remaining.pending,g.currency)}`),`max="${Math.max(0,remaining.remaining-remaining.pending)}"`)}${field(tr('Allocate to optional emergency fund','分配至可选应急基金'),'emergency',0,'number',p.currency===g.currency?tr('This allocation never counts towards the main goal.','此分配不会计入主目标。'):tr(`Emergency allocation must be in ${p.currency}; use a separate deposit if the goal currency differs.`,`应急分配须使用${p.currency}。目标币种不同时，请另行记录。`),S().emergency.enabled?'':'disabled')}</div><label class="upload mt">${icon('upload')}<div class="bold small">${tr('Upload transaction evidence','上传交易凭证')}</div><div class="small muted mt8">${tr('PNG, JPG or PDF · up to 5 MB · stored on this browser','PNG、JPG或PDF · 最大5 MB · 保存在此浏览器')}</div><input name="receipt" type="file" accept="image/png,image/jpeg,application/pdf" required aria-label="${tr('Transaction evidence file','交易凭证文件')}"></label><label class="check mt"><input name="newTransfer" type="checkbox" required>${tr('This is a new transfer into my own account, not an opening balance or a receipt already credited elsewhere in this app.','这是转入我自己账户的新增转账，并非起始余额，也不是此应用已计入的凭证。')}</label>${error}<div class="form-actions"><button class="btn" type="submit">${tr('Submit evidence for local review','提交凭证供本地审阅')}</button></div></form>`);}
  function reviewModal(id){const t=S().ledger.find(t=>t.id===id);if(!t||t.status!=='pending')return;openModal(tr('Review your evidence','审阅你的凭证'),`${notice(tr('These automated checks do not prove bank settlement. Compare the receipt and your bank app yourself. This is a transparent local-demo review, not an independent bank verification.','这些自动检查不能证明银行到账。请亲自比对凭证与银行应用。这是透明的本地演示审阅，并非独立银行验证。'),'warn')}<div class="cost-list mt"><div class="cost-row"><span>${esc(t.reference)}</span><strong>${cash(t.amount,t.currency)}</strong></div><div class="cost-row"><span>${tr('Personal goal','个人目标')}</span><strong>${cash(t.main,t.currency)}</strong></div><div class="cost-row"><span>${tr('Emergency allocation','应急分配')}</span><strong>${cash(t.emergency,t.currency)}</strong></div></div><div class="review-checks mt12">${['File signature checked','Unique reference checked','Duplicate file hash checked','Allocation total checked'].map((en,i)=>`<span>${icon('check')}${tr(en,['已检查文件签名','已检查唯一参考号','已检查重复文件哈希','已检查分配总额'][i])}</span>`).join('')}</div><button class="textbtn mt12" data-action="v2-evidence:${id}">${tr('View uploaded receipt','查看已上传凭证')}</button><form id="v2-review-form" data-id="${id}"><label class="check mt"><input name="attested" type="checkbox" required>${tr('I personally checked the amount, date and reference against my receipt and bank account. I understand this does not make the app a bank-settlement verifier.','我已亲自把金额、日期和参考号与凭证及银行账户比对。我理解应用并不因此成为银行到账验证方。')}</label>${error}<div class="form-actions">${b(tr('Reject this record','拒绝此记录'),`reject:${id}`,'secondary','type="button"')}<button class="btn" type="submit">${tr('Confirm my local evidence review','确认我的本地凭证审阅')}</button></div></form>`);}
  async function action(a){const [kind,id,extra]=a.split(':');if(kind==='onboard'){setupModal();return true;}if(kind==='library'){library=true;navigate('story');return true;}if(kind==='reminders'){navigate('savings');return true;}if(kind==='deposit'){depositModal();return true;}if(kind==='review'&&S().ledger.find(t=>t.id===id)?.goalId){reviewModal(id);return true;}if(!kind.startsWith('v2-'))return false;
    if(kind==='v2-setup'||kind==='v2-newgoal'){setupModal(kind==='v2-newgoal');return true;}
    if(kind==='v2-setup-back'){draft={...draft,...formValues(document.querySelector('#v2-setup-form'))};setupStep=Math.max(0,setupStep-1);showSetup();return true;}
    if(kind==='v2-sample'){draft={...draft,...formValues(document.querySelector('#v2-setup-form'))};const sg=draft.country==='SG';Object.assign(draft,{income:5000,fixed:sg?1300:1000,living:sg?1100:1500,discretionary:500,loans:500,emergency:100});showSetup();toast(tr('Sample figures loaded. Review them before approving your goal.','已载入示例数字，请在批准目标前审阅。'));return true;}
    if(kind==='v2-library'){library=true;closeModal();navigate('story');return true;}
    if(kind==='v2-journal'){library=false;closeModal();navigate('story');return true;}
    if(kind==='v2-preview'){preview(id);return true;}
    if(kind==='v2-trigger'){D.triggerIncident(S(),Number(id));save();library=false;navigate('story');return true;}
    if(kind==='v2-choice'){pendingChoice={incidentId:id,optionId:extra,mode:'portion',share:100};choiceModal();return true;}
    if(kind==='v2-preview-plan'){const values=formValues(document.querySelector('#v2-decision-form'));pendingChoice={...pendingChoice,...values};choiceModal();return true;}
    if(kind==='v2-finish'){D.finishIncident(S(),id);save();render();window.scrollTo({top:0,behavior:'smooth'});toast(tr('One page lived. The next incident stays a surprise.','体验完一页，下一事件仍是惊喜。'));return true;}
    if(kind==='v2-goal'){goalModal();return true;}if(kind==='v2-adjustgoal'){adjustGoalModal();return true;}if(kind==='v2-pause'){pauseModal();return true;}if(kind==='v2-checkpoint'){checkpointModal();return true;}if(kind==='v2-quotes'){quotesModal();return true;}if(kind==='v2-deposit'){depositModal();return true;}
    if(kind==='v2-evidence'){const file=await evidenceStore('get',id);if(!file)throw Error(tr('This receipt is not stored on this browser. Backups contain records but not receipt files.','此浏览器未保存该凭证。备份包含记录，但不包含凭证文件。'));const url=URL.createObjectURL(file);const old=()=>URL.revokeObjectURL(url);const d=document.querySelector('#modal');const restoreId=id;openModal(tr('Your local receipt','你的本地凭证'),`${file.type==='application/pdf'?`<object data="${url}" type="application/pdf" width="100%" height="450"><a href="${url}" target="_blank">${tr('Open PDF receipt','打开PDF凭证')}</a></object>`:`<img src="${url}" alt="${tr('Uploaded transaction evidence','上传的交易凭证')}" style="max-width:100%;max-height:55vh;display:block;margin:auto">`}<div class="form-actions">${S().ledger.find(t=>t.id===restoreId)?.status==='pending'?b(tr('Back to receipt review','返回凭证审阅'),`review:${restoreId}`,'secondary'):b(tr('Close receipt','关闭凭证'),'close','secondary')}</div>`);d.addEventListener('close',old,{once:true});return true;}
    return false;
  }
  async function submit(f){if(f.id==='emergency-form'&&Q()){const v=formValues(f),p=P(),monthly=v.enabled?v.monthly:0;if(G.exchange(monthly,p.currency,Q().currency,p.fx)>Q().comfortableMonthly)throw Error(tr('This emergency contribution exceeds your approved comfortable total. Lower it or explicitly adjust your goal limit first.','此应急供款超过已批准的舒适总额。请降低供款，或先明确调整目标限额。'));return false;}if(!f.id.startsWith('v2-'))return false;const d=formValues(f);
    if(f.id==='v2-setup-form'){draft={...draft,...d};if(setupStep<2){if(setupStep===0&&(draft.amount<=0||draft.comfortableMonthly<0||!Number.isInteger(draft.months)||draft.months<1||draft.months>120))throw Error(tr('Enter a positive goal, a non-negative limit, and 1–120 months.','请输入正数目标、非负限额及1–120个月时长。'));setupStep++;showSetup();return true;}const current=P(),currency=draft.country==='MY'?'MYR':'SGD';if(current&&current.country!==draft.country)throw Error(tr('Change residence in your personal profile first, confirming the actual balances in the new currency. Your existing data stays intact.','请先在个人档案中更改居住国家，并确认新币种的真实余额。现有数据保持完整。'));const next={...current,...draft,currency,effective:E.today(),savings:current?E.recordedSavings(S(),current):0,reserves:current?E.reserves(S(),current):0,excludedTransactionIds:S().ledger.filter(t=>t.status==='confirmed').map(t=>t.id)};const cap=E.capacity(next),emergencyGoal=G.exchange(next.emergency,currency,draft.currency,next.fx);if(next.emergency>Math.max(0,cap.raw+next.emergency)||emergencyGoal>draft.comfortableMonthly)throw Error(tr('Lower the optional emergency contribution to fit your actual budget and comfortable total limit.','请降低可选应急供款，使其符合真实预算及舒适总限额。'));const oldVersions=S().versions.length;try{E.profileVersion(S(),next);G.createGoal(S(),{amount:draft.amount,months:draft.months,comfortableMonthly:draft.comfortableMonthly,currency:draft.currency,name:draft.goalName});}catch(e){S().versions.splice(oldVersions);throw e;}S().name=String(draft.name||'Alex').trim();S().language=draft.language;S().onboarded=true;S().emergency={...S().emergency,enabled:next.emergency>0,monthly:next.emergency};const s=J();if(s)s.currency=Q().currency;save();closeModal();library=!s||s.completed;navigate('story');return true;}
    if(f.id==='v2-story-form'){if(!Q()){setupModal();return true;}const s=D.startJourney(S(),selectedStory,{knownTwins:!!d.knownTwins,...(selectedStory==='travel'?{destination:d.destination,travellers:d.travellers}:{} )});D.triggerIncident(S(),s.v2.turn);save();closeModal();library=false;navigate('story');return true;}
    if(f.id==='v2-decision-form'){D.decideIncident(S(),pendingChoice.incidentId,pendingChoice.optionId,{mode:d.mode,proportion:d.share/100});pendingChoice=null;save();closeModal();render();return true;}
    if(f.id==='v2-goal-form'){G.adjustGoal(S(),{amount:d.amount,months:d.months,comfortableMonthly:d.comfortableMonthly,reason:d.reason});save();closeModal();render();toast(tr('Your approved adjustment is recorded.','你批准的调整已记录。'));return true;}
    if(f.id==='v2-pause-form'){G.pauseGoal(S(),!Q().paused,d.reason);save();closeModal();render();return true;}
    if(f.id==='v2-checkpoint-form'){D.reviseIncidentChallenge(S(),J().v2.current.id,d.target,d.reason);save();closeModal();render();return true;}
    if(f.id==='v2-quotes-form'){const quotes={};for(const [key,value]of Object.entries(d))if(key.startsWith('quote_'))quotes[key.slice(6)]=value;D.quoteIncident(S(),J().v2.current.id,quotes,d.reason);save();closeModal();render();return true;}
    if(f.id==='v2-deposit-form'){const file=f.querySelector('[name="receipt"]').files[0];if(!file)throw Error(tr('Upload transaction evidence first.','请先上传交易凭证。'));const bytes=await file.arrayBuffer(),inspection=G.inspectEvidence(bytes,file.type),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(b=>b.toString(16).padStart(2,'0')).join('');const t=G.submitEvidence(S(),{storyId:J().id,currency:d.currency,amount:d.amount,main:d.main||0,emergency:d.emergency||0,date:d.date,reference:d.reference,fileName:file.name,hash,evidence:inspection});try{await evidenceStore('put',t.id,file);}catch{S().ledger=S().ledger.filter(r=>r.id!==t.id);throw Error(tr('Receipt storage failed. Nothing was credited or submitted.','凭证储存失败，没有任何金额被计入或提交。'));}save();closeModal();navigate('savings');reviewModal(t.id);return true;}
    if(f.id==='v2-review-form'){G.verifyEvidence(S(),f.dataset.id,d.attested);save();closeModal();render();toast(G.goalProgress(S()).complete?tr('Your personal savings goal is achieved. The story can keep going.','个人储蓄目标已达成，故事仍可继续。'):tr('Evidence reviewed locally. Your contribution is recorded once.','本地凭证审阅完成，供款已计入一次。'));return true;}
    return false;
  }
  return {action,submit,renderPage(page){G.ensureGame(S());if(page==='home')return home();if(page==='story')return journal();if(page==='savings')return savings();if(page==='profile')return goalPanel()+ctx.legacyProfilePage();if(page==='finance')return `<div class="notice blue mb">${tr('Personal limits and a virtual sandbox. These tools support a game, not a real purchase plan. Virtual assets and expenses stay separate from actual records.','个人限额与虚拟沙盒。这些工具用于游戏，并非真实购买计划。虚拟资产和开支保持独立于真实记录。')}</div>`+ctx.legacyFinancePage();return null;}};
}
